stItem", "content": [{"type": "paragraph", "content": [{"type": "text", "text": "忽略等待时间的优化"}]}]}]}, {"type": "highlightBlock", "attrs": {"backgroundColor": "#eff6ff", "borderColor": "#3b82f6", "icon": "📊"}, "content": [{"type": "paragraph", "content": [{"type": "text", "text": "刷题建议：", "marks": [{"type": "bold"}]}, {"type": "text", "text": "时间安排的关键是\"能并行就并行\"。找出关键路径，优化等待时间。"}]}]}]}$$ AS jsonb), NULL, '数量关系-统筹规划问题-时间安排的核心知识点和解题方法。', category_node.id, CAST('["数量关系", "统筹规划问题", "时间安排"]' AS jsonb), FALSE, TRUE, TRUE, NOW(), 0, 0, CAST('{"content_type": "knowledge_point", "category_code": "kp_plan_time", "source": "fba_content_engine"}' AS jsonb), 1, NOW()
